import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 for non-empty cart", () => {
    const lines = [makeLine("a", 500, 2)];
    expect(calc.computeShippingCents(lines, 5000)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(9.99)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
    });

    it("accepts valid inputs", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
      expect(() => new FlatShippingCalculator(500, 5000)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns flatCents for non-empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      const lines = [makeLine("a", 100, 1)];
      expect(calc.computeShippingCents(lines, 2000)).toBe(799);
    });

    it("returns 0 when subtotal >= freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      const lines = [makeLine("a", 100, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
      expect(calc.computeShippingCents(lines, 6000)).toBe(0);
    });

    it("returns flatCents when subtotal < freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      const lines = [makeLine("a", 100, 1)];
      expect(calc.computeShippingCents(lines, 4999)).toBe(799);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects invalid overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weights defined)", () => {
      const lines = [makeLine("a", undefined, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects first bracket when weight <= upToGrams", () => {
      const lines = [makeLine("a", 250, 1)]; // 250g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects bracket at boundary", () => {
      const lines = [makeLine("a", 500, 1)]; // exactly 500g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects second bracket when weight exceeds first", () => {
      const lines = [makeLine("a", 501, 1)]; // 501g
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects last bracket at its boundary", () => {
      const lines = [makeLine("a", 5000, 1)]; // 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const lines = [makeLine("a", 5001, 1)]; // 5001g
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("uses heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      const lines = [makeLine("a", 5000, 1)];
      expect(calcNoOverflow.computeShippingCents(lines, 1000)).toBe(900);
    });

    it("sums weight across multiple lines and quantities", () => {
      // 200g * 2 + 300g * 1 = 700g → second bracket (700)
      const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      const lines = [makeLine("a", 250, 1)];
      expect(unordered.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500, weightGrams: 300 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a new product to the cart", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities for the same product id", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("throws for non-positive integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("throws for negative unit price", () => {
      const cart = new Cart();
      const badProduct = { ...productA, unitPriceCents: -1 };
      expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity for existing product", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of lines", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.id).toBe("a");
      expect(snap[0]!.quantity).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2500
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4500);
    });

    it("applies discount via the injected policy", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 3); // subtotal = 3000
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(3000);
    });

    it("clamps discount to [0, subtotal]", () => {
      // Discount greater than subtotal
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 99999,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 1); // subtotal = 1000
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(productA, 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 200,
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
      cart.add(productA, 1); // subtotal = 1000, discounted = 800
      const totals = cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      expect(totals.taxCents).toBe(80);
    });

    it("computes shipping with discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(799),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(productA, 2); // subtotal = 2000, discounted = 1500
      const totals = cart.totals();
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        1500,
      );
      expect(totals.shippingCents).toBe(799);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => 72,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
      cart.add(productA, 1); // subtotal = 1000
      const totals = cart.totals();
      // discounted = 900, tax = 72, shipping = 500
      expect(totals.totalCents).toBe(900 + 72 + 500);
    });

    it("empty cart has all zero totals", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("defaults region to US", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(productA, 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => -50,
      };
      const cart = new Cart({ taxCalculator });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000, weightGrams: 200 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns current totals and lines snapshot", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });

  describe("priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const cart = new Cart();
      cart.add(productA, 1); // original price 1000
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1500);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("throws RangeError for invalid fetched price", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-1),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws RangeError for non-integer fetched price", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch failed");
    });
  });

  describe("inventoryChecker", () => {
    it("passes when all items are available", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 1);
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(4000);
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("throws InventoryError when item unavailable", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };
      const cart = new Cart();
      cart.add(productA, 3);
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(3);
        expect(invErr.available).toBeUndefined();
        expect(invErr.message).toBe("out of stock");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1,
        }),
      };
      const cart = new Cart();
      cart.add(productA, 5);
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(1);
      }
    });

    it("InventoryError has correct name property", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect((err as InventoryError).name).toBe("InventoryError");
      }
    });
  });

  describe("asyncTaxProvider", () => {
    it("uses async tax rate for totals computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart();
      cart.add(productA, 1); // subtotal = 1000, no discount, tax = 10% of 1000 = 100
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies discount before async tax", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
      });
      cart.add(productA, 1); // subtotal = 1000, 20% off = 200, taxable = 800, tax = 80
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
    });

    it("includes shipping in total with async tax", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const cart = new Cart({
        shippingCalculator: new FlatShippingCalculator(500),
      });
      cart.add(productA, 1); // subtotal = 1000, tax = 5% of 1000 = 50, shipping = 500
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(1000 + 50 + 500);
    });

    it("propagates async tax provider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });
  });

  describe("full pipeline with all collaborators", () => {
    it("refreshes prices, checks inventory, and uses async tax", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(600),
      });
      cart.add(productA, 2);
      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });
      // refreshed price: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // 10% discount: floor(2400 * 10 / 100) = 240
      expect(result.totals.discountCents).toBe(240);
      // taxable = 2400 - 240 = 2160, tax = floor(2160 * 0.08) = 172
      expect(result.totals.taxCents).toBe(172);
      // shipping = 600
      expect(result.totals.shippingCents).toBe(600);
      // total = 2160 + 172 + 600 = 2932
      expect(result.totals.totalCents).toBe(2932);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { refreshPrices, InventoryError } from "../src/inventory.ts";
