toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 for non-empty cart", () => {
    const lines = [makeLine("a", 500, 2)];
    expect(calc.computeShippingCents(lines, 5000)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(9.99)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
    });

    it("accepts valid inputs", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
      expect(() => new FlatShippingCalculator(500, 5000)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns flatCents for non-empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      const lines = [makeLine("a", 100, 1)];
      expect(calc.computeShippingCents(lines, 2000)).toBe(799);
    });

    it("returns 0 when subtotal >= freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      const lines = [makeLine("a", 100, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
      expect(calc.computeShippingCents(lines, 6000)).toBe(0);
    });

    it("returns flatCents when subtotal < freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      const lines = [makeLine("a", 100, 1)];
      expect(calc.computeShippingCents(lines, 4999)).toBe(799);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects invalid overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weights defined)", () => {
      const lines = [makeLine("a", undefined, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects first bracket when weight <= upToGrams", () => {
      const lines = [makeLine("a", 250, 1)]; // 250g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects bracket at boundary", () => {
      const lines = [makeLine("a", 500, 1)]; // exactly 500g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects second bracket when weight exceeds first", () => {
      const lines = [makeLine("a", 501, 1)]; // 501g
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects last bracket at its boundary", () => {
      const lines = [makeLine("a", 5000, 1)]; // 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const lines = [makeLine("a", 5001, 1)]; // 5001g
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("uses heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      const lines = [makeLine("a", 5000, 1)];
      expect(calcNoOverflow.computeShippingCents(lines, 1000)).toBe(900);
    });

    it("sums weight across multiple lines and quantities", () => {
      // 200g * 2 + 300g * 1 = 700g → second bracket (700)
      const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      const lines = [makeLine("a", 250, 1)];
      expect(unordered.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

